def ab_schema__trello__TrelloState__find_actions(self, action_key, filters):
    records = model_get(self, 'actions').get(action_key, [])
    if not filters:
        return list(records)
    results = []
    for record in records:
        match = True
        for key, value in filters.items():
            if value is None:
                continue
            if key not in model_get(record, 'params'):
                continue
            if model_get(record, 'params').get(key) != value:
                match = False
                break
        if match:
            results.append(record)
    return results

