    prop = assertion.get('property')
    value = assertion.get('value')
    if not prop:
        return False
    for contact in model_get(model_get(world, 'hubspot'), 'contacts'):
        if contact_id and model_get(contact, 'id') != contact_id:
            continue
        if email and (not model_get(contact, 'email') or model_get(contact, 'email').lower() != email.lower()):
            continue
        actual_value = model_get(contact, prop, None)
        if actual_value is None:
            actual_value = model_get(contact, 'properties').get(prop)
        if value is None:
            if actual_value is not None:
                return True
        elif actual_value is not None:
            if str(actual_value).lower() == str(value).lower():
                return True
            try:
                if float(actual_value) == float(value):
                    return True
            except (ValueError, TypeError):
                pass
    return False

