def ab_tools__api__impl__google_sheets___was_row_updated(world, ss_id, row_id, ws_id=None):
    """Check if a row was modified during this task execution."""
    updated = model_get(model_get(world, 'google_sheets'), '_updated_row_keys', set())
    if ws_id:
        return f'{ss_id}:{ws_id}:{row_id}' in updated
    prefix = f'{ss_id}:'
    suffix = f':{row_id}'
    return any((k.startswith(prefix) and k.endswith(suffix) for k in updated))

